package in.recallradar;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
enum OrganizationRole { ORG_ADMIN, FOOD_SAFETY_MANAGER, WAREHOUSE_MANAGER, OUTLET_MANAGER, OUTLET_STAFF, AUDITOR }
enum LocationType { WAREHOUSE, CENTRAL_KITCHEN, OUTLET }
@Entity @Table(name="organization") class Organization { @Id UUID id; String name; @Column(unique=true) String slug; Instant createdAt; protected Organization(){} Organization(String n,String s){id=UUID.randomUUID();name=n;slug=s;createdAt=Instant.now();} }
@Entity @Table(name="org_membership",uniqueConstraints=@UniqueConstraint(columnNames={"userId","organizationId"})) class Membership { @Id UUID id; UUID userId; UUID organizationId; @Enumerated(EnumType.STRING) OrganizationRole role; Instant createdAt; protected Membership(){} Membership(UUID u,UUID o,OrganizationRole r){id=UUID.randomUUID();userId=u;organizationId=o;role=r;createdAt=Instant.now();} }
@Entity @Table(name="location") class Location { @Id UUID id; UUID organizationId; String name; @Enumerated(EnumType.STRING) LocationType type; String address; boolean active=true; Instant createdAt; protected Location(){} Location(UUID o,String n,LocationType t,String a){id=UUID.randomUUID();organizationId=o;name=n;type=t;address=a;createdAt=Instant.now();} }
@Entity @Table(name="supplier") class Supplier { @Id UUID id; UUID organizationId; String name; String contactName; String email; String phone; boolean active=true; Instant createdAt; protected Supplier(){} Supplier(UUID o,String n,String c,String e,String p){id=UUID.randomUUID();organizationId=o;name=n;contactName=c;email=e;phone=p;createdAt=Instant.now();} }
@Entity @Table(name="ingredient") class Ingredient { @Id UUID id; UUID organizationId; String name; String category; String unit; boolean active=true; Instant createdAt; protected Ingredient(){} Ingredient(UUID o,String n,String c,String u){id=UUID.randomUUID();organizationId=o;name=n;category=c;unit=u;createdAt=Instant.now();} }
@Entity @Table(name="supplier_ingredient") @IdClass(SupplierIngredientId.class) class SupplierIngredient { @Id UUID supplierId; @Id UUID ingredientId; String supplierSku; protected SupplierIngredient(){} SupplierIngredient(UUID s,UUID i,String sku){supplierId=s;ingredientId=i;supplierSku=sku;} }
class SupplierIngredientId implements java.io.Serializable { UUID supplierId; UUID ingredientId; public SupplierIngredientId(){} public int hashCode(){return java.util.Objects.hash(supplierId,ingredientId);} public boolean equals(Object o){return o instanceof SupplierIngredientId x&&java.util.Objects.equals(supplierId,x.supplierId)&&java.util.Objects.equals(ingredientId,x.ingredientId);} }
